catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    // Get Source and Destination
    var source = g_form.getValue('starting_from');
    var destination = g_form.getValue('going_to');

    // Passenger Count
    var numPassengers = Number(newValue);

    // Get Journey Type
    var journeyType = g_form.getValue('type_of_journey');

    // Ameerpet → Madhapur
    if (source == 'c5156e9747038710151364f2e16d4383' &&
        destination == 'e7546b5b47030310151364f2e16d4354') {

        if (journeyType == '1') {
            g_form.setValue(
                'amount_for_single_journey',
                numPassengers * 30
            );
            g_form.clearValue('amount_including_return');

        } else if (journeyType == '2') {
            g_form.clearValue('amount_for_single_journey');
            g_form.setValue(
                'amount_including_return',
                numPassengers * 60
            );
        }
    }

    // Ameerpet → LB Nagar
    else if (source == 'c5156e9747038710151364f2e16d4383' &&
        destination == '96742f5b47030310151364f2e16d4379') {

        if (journeyType == '1') {
            g_form.setValue(
                'amount_for_single_journey',
                numPassengers * 50
            );
            g_form.clearValue('amount_including_return');

        } else if (journeyType == '2') {
            g_form.clearValue('amount_for_single_journey');
            g_form.setValue(
                'amount_including_return',
                numPassengers * 100
            );
        }
    }

    // Ameerpet → Kukatpally
    else if (source == 'c5156e9747038710151364f2e16d4383' &&
        destination == 'e494275b47030310151364f2e16d4388') {

        if (journeyType == '1') {
            g_form.setValue(
                'amount_for_single_journey',
                numPassengers * 30
            );
            g_form.clearValue('amount_including_return');

        } else if (journeyType == '2') {
            g_form.clearValue('amount_for_single_journey');
            g_form.setValue(
                'amount_including_return',
                numPassengers * 60
            );
        }
    }

    // Ameerpet → Jubilee Hills
    else if (source == 'c5156e9747038710151364f2e16d4383' &&
        destination == 'daa4a39b47030310151364f2e16d4328') {

        if (journeyType == '1') {
            g_form.setValue(
                'amount_for_single_journey',
                numPassengers * 20
            );
            g_form.clearValue('amount_including_return');

        } else if (journeyType == '2') {
            g_form.clearValue('amount_for_single_journey');
            g_form.setValue(
                'amount_including_return',
                numPassengers * 40
            );
        }
    } else {
        g_form.clearValue('amount_for_single_journey');
        g_form.clearValue('amount_including_return');
    }
}
